-- Fixture-only transactions. Every probe rolls back, even if a policy regresses.
begin;
select no_plan();
create function pg_temp.fixture_id(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.fixture_id(703),'isolation-staff@example.test'),(pg_temp.fixture_id(704),'isolation-a@example.test'),(pg_temp.fixture_id(705),'isolation-b@example.test');
update public.profiles set role='staff' where id=pg_temp.fixture_id(703);
insert into public.brands(id,name) values(pg_temp.fixture_id(701),'Isolation A'),(pg_temp.fixture_id(702),'Isolation B');
insert into public.brand_users(brand_id,user_id) values(pg_temp.fixture_id(701),pg_temp.fixture_id(704)),(pg_temp.fixture_id(702),pg_temp.fixture_id(705));
insert into public.customers(id,legal_name) values(pg_temp.fixture_id(706),'Isolation customer');
insert into public.customer_contacts(customer_id,name) values(pg_temp.fixture_id(706),'Private customer contact');
create temporary table isolation_scopes(scope text,brand_id uuid,season_id uuid,product_id uuid,variant_id uuid,order_id uuid,budget_id uuid,event_id uuid,document_id uuid,user_id uuid);
insert into isolation_scopes values('A',pg_temp.fixture_id(701),pg_temp.fixture_id(710),pg_temp.fixture_id(720),pg_temp.fixture_id(730),null,pg_temp.fixture_id(740),pg_temp.fixture_id(750),pg_temp.fixture_id(760),pg_temp.fixture_id(704)),('B',pg_temp.fixture_id(702),pg_temp.fixture_id(711),pg_temp.fixture_id(721),pg_temp.fixture_id(731),null,pg_temp.fixture_id(741),pg_temp.fixture_id(751),pg_temp.fixture_id(761),pg_temp.fixture_id(705));
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000703';
do $$declare s record;v_order uuid;begin
for s in select * from isolation_scopes loop
insert into public.brand_private(id,notes) values(s.brand_id,'Private brand');
insert into public.brand_contacts(brand_id,name) values(s.brand_id,'Private contact');
insert into public.seasons(id,brand_id,code,name) values(s.season_id,s.brand_id,'ISOLATION','Isolation season');
insert into public.products(id,brand_id,season_id,sku_base,name,wholesale_price_cents) values(s.product_id,s.brand_id,s.season_id,'ISOLATION-'||s.scope,'Isolation product',1000);
insert into public.product_variants(id,brand_id,product_id,size,color,sku) values(s.variant_id,s.brand_id,s.product_id,'M','Nero','ISOLATION-'||s.scope||'-M');
v_order:=public.save_order(null,jsonb_build_object('brand_id',s.brand_id,'customer_id',pg_temp.fixture_id(706),'season_id',s.season_id,'order_date','2033-01-01','discount_pct',0,'internal_notes','Isolation secret'),jsonb_build_array(jsonb_build_object('variant_id',s.variant_id,'quantity',1,'unit_price_cents',1000,'discount_pct',0)));
perform public.change_order_status(v_order,'confirmed','');
update isolation_scopes set order_id=v_order where scope=s.scope;
insert into public.budgets(id,brand_id,amount_cents,period_start,period_end) values(s.budget_id,s.brand_id,5000,'2033-01-01','2033-12-31');
insert into public.budget_private(id,brand_id,notes) values(s.budget_id,s.brand_id,'Private budget');
insert into public.invoices(number,brand_id,customer_id,order_id,status,issue_date,due_date,net_cents,vat_cents,gross_cents) values('ISOLATION-'||s.scope,s.brand_id,pg_temp.fixture_id(706),v_order,'issued','2033-01-01','2033-02-01',1000,220,1220);
insert into public.invoice_counters(brand_id,year,last_number) values(s.brand_id,2033,1);
insert into public.mock_invoice_records(id,brand_id,idempotency_key,external_id,fingerprint,status) select id,s.brand_id,idempotency_key,'mock_'||id::text,repeat('a',64),'issued' from public.invoices where number='ISOLATION-'||s.scope;
insert into public.invoice_webhook_events(event_id,provider,invoice_id,brand_id,external_status) select 'isolation-'||s.scope,'mock',id,s.brand_id,'issued' from public.invoices where number='ISOLATION-'||s.scope;
insert into public.payments(invoice_id,brand_id,amount_cents,paid_at,method) select id,s.brand_id,100,'2033-01-02T10:00Z','bank_transfer' from public.invoices where number='ISOLATION-'||s.scope;
insert into public.events(id,brand_id,title,starts_at,ends_at,visible_to_brand,assigned_to) values(s.event_id,s.brand_id,'Shared isolation','2033-01-01T09:00Z','2033-01-01T10:00Z',true,pg_temp.fixture_id(703));
insert into public.event_reminders(event_id,recipient_id,starts_at) values(s.event_id,pg_temp.fixture_id(703),'2033-01-01T09:00Z');
insert into public.documents(id,name,brand_id,storage_path,original_filename,mime_type,size_bytes,uploaded_by,shared_with_brand) values(s.document_id,'Shared isolation',s.brand_id,s.brand_id::text||'/'||s.document_id::text||'.pdf','isolation.pdf','application/pdf',10,pg_temp.fixture_id(703),true);
insert into storage.objects(bucket_id,name,metadata) values('documents',s.brand_id::text||'/'||s.document_id::text||'.pdf','{"size":10,"mimetype":"application/pdf"}');
update public.documents set ready=true where id=s.document_id;
insert into public.ical_tokens(user_id,token_hash) values(s.user_id,repeat(case when s.scope='A' then 'a' else 'b' end,64));
end loop;end;$$;
insert into storage.buckets(id,name,public) values('isolation-other','isolation-other',false);

update public.invoices set status='draft' where number like 'ISOLATION-%';
insert into isolation_scopes select 'C',brand_id,season_id,product_id,variant_id,
public.save_order(null,jsonb_build_object('brand_id',brand_id,'customer_id',pg_temp.fixture_id(706),'season_id',season_id,'order_date','2033-01-01','discount_pct',0),jsonb_build_array(jsonb_build_object('variant_id',variant_id,'quantity',1,'unit_price_cents',1000,'discount_pct',0))),budget_id,event_id,document_id,user_id from isolation_scopes where scope='A';
select public.change_order_status(order_id,'confirmed','') from isolation_scopes where scope='C';
create temporary table billing_fixture(scope text primary key,invoice_id uuid,lease uuid,external_id text,payment_key uuid default gen_random_uuid());
insert into billing_fixture(scope) values('A'),('B'),('C');grant all on billing_fixture,isolation_scopes to authenticated,service_role;
set local role authenticated;
select throws_ok($$select public.reserve_invoice_from_order(order_id,'2033-01-02','2033-02-02','mock') from isolation_scopes where scope='A'$$,'42501',null,'staff cannot emit invoices');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000703';
reset role;update public.profiles set role='accounting' where id=pg_temp.fixture_id(703);set local role authenticated;
select throws_ok($$select public.reserve_invoice_from_order(order_id,'2033-01-02','2033-02-02','mock') from isolation_scopes where scope='A'$$,'23514',null,'confirmed order is not invoiceable');
reset role;update public.profiles set role='staff' where id=pg_temp.fixture_id(703);set local role authenticated;
select public.change_order_status(order_id,'in_production','') from isolation_scopes;
select public.change_order_status(order_id,'shipped','') from isolation_scopes;
select public.change_order_status(order_id,'delivered','') from isolation_scopes;
select throws_ok($$select public.change_order_status(order_id,'invoiced','') from isolation_scopes where scope='A'$$,'23514',null,'actual issued invoice required before order transition');
reset role;update public.profiles set role='accounting' where id=pg_temp.fixture_id(703);set local role authenticated;
select lives_ok($$update billing_fixture f set invoice_id=public.reserve_invoice_from_order(s.order_id,'2033-01-02','2033-02-02','mock') from isolation_scopes s where s.scope=f.scope$$,'reserve invoice and fiscal snapshots');
select is((select public.reserve_invoice_from_order(order_id,'2033-01-02','2033-02-02','mock') from isolation_scopes where scope='A'),(select invoice_id from billing_fixture where scope='A'),'reserve retries have one invoice');
select throws_ok($$select public.reserve_invoice_from_order(order_id,'2033-01-02','2033-03-02','mock') from isolation_scopes where scope='A'$$,'23505',null,'changed reserve input conflicts rather than rewriting snapshots');
select is((select count(*) from public.invoices where provider='mock' and order_id=(select order_id from isolation_scopes where scope='A')),1::bigint,'no duplicate business invoice');
update billing_fixture set lease=public.claim_invoice_issue(invoice_id),external_id='mock_'||invoice_id::text;
select throws_ok($$select public.claim_invoice_issue(invoice_id) from billing_fixture where scope='A'$$,'55P03',null,'active issuance lease excludes concurrent processor');
select is((select public.finish_invoice_issue(invoice_id,gen_random_uuid(),external_id,'issued') from billing_fixture where scope='A'),false,'stale lease cannot finalize');
select throws_ok($$select public.finish_invoice_issue(invoice_id,lease,external_id,'issued') from billing_fixture where scope='A'$$,'23514',null,'mock status must reference durable provider record');
select is((select public.fail_invoice_issue(invoice_id,lease,'provider_unavailable') from billing_fixture where scope='A'),true,'failure releases issuance for retry');
update billing_fixture set lease=public.claim_invoice_issue(invoice_id) where scope='A';
select lives_ok($$select public.mock_invoice_put(i.id,i.idempotency_key,repeat('d',64),'issued') from public.invoices i join billing_fixture f on f.invoice_id=i.id where f.scope='A'$$,'provider simulation persists without an isolate-local map');
select lives_ok($$select public.mock_invoice_put(i.id,i.idempotency_key,repeat('d',64),'issued') from public.invoices i join billing_fixture f on f.invoice_id=i.id where f.scope='A'$$,'provider retry uses the same record');
select throws_ok($$select public.mock_invoice_put(i.id,i.idempotency_key,repeat('e',64),'issued') from public.invoices i join billing_fixture f on f.invoice_id=i.id where f.scope='A'$$,'23505',null,'provider fingerprint conflict is rejected');
select is((select public.finish_invoice_issue(invoice_id,lease,external_id,'issued') from billing_fixture where scope='A'),true,'finalize invoice and order atomically');
select is((select status::text from public.orders where id=(select order_id from isolation_scopes where scope='A')),'invoiced','emission advances order');
select is((select net_cents from public.v_revenue_by_brand_period where brand_id=pg_temp.fixture_id(701)),'1000','issued invoice contributes to revenue');
select is((select count(*) from public.audit_log where table_name='invoices' and record_id=(select invoice_id from billing_fixture where scope='A')),0::bigint,'accounting cannot read invoice audit history');
select lives_ok($$select public.register_invoice_payment(invoice_id,payment_key,500,'2033-01-03T12:00Z','bank_transfer','First') from billing_fixture where scope='A'$$,'partial payment registered');
select lives_ok($$select public.register_invoice_payment(invoice_id,payment_key,500,'2033-01-03T12:00Z','bank_transfer','First') from billing_fixture where scope='A'$$,'payment retry is idempotent');
select is((select count(*) from public.payments where invoice_id=(select invoice_id from billing_fixture where scope='A')),1::bigint,'payment is inserted once');
select throws_ok($$select public.register_invoice_payment(invoice_id,payment_key,501,'2033-01-03T12:00Z','bank_transfer','First') from billing_fixture where scope='A'$$,'23505',null,'changed payment retry conflicts');
select throws_ok($$select public.register_invoice_payment(invoice_id,gen_random_uuid(),2000,'2033-01-03T12:00Z','bank_transfer','') from billing_fixture where scope='A'$$,'23514',null,'overpayment rejected');
select is((select balance_cents from public.v_invoice_balances where id=(select invoice_id from billing_fixture where scope='A')),'720','SQL balance is exact');
select lives_ok($$select public.register_invoice_payment(invoice_id,gen_random_uuid(),720,'2033-01-04T12:00Z','cash','Balance') from billing_fixture where scope='A'$$,'final payment settles invoice');
select is((select status::text from public.invoices where id=(select invoice_id from billing_fixture where scope='A')),'paid','ledger drives paid status');
select is((select status::text from public.mock_invoice_records where id=(select invoice_id from billing_fixture where scope='A')),'paid','mock state persists the settled simulation');
select throws_ok($$select public.register_invoice_payment(invoice_id,gen_random_uuid(),1,'2033-01-04T12:00Z','cash','') from billing_fixture where scope='A'$$,'23514',null,'settled invoice cannot receive another payment');
select public.mock_invoice_put(i.id,i.idempotency_key,repeat('c',64),'issued') from public.invoices i join billing_fixture f on f.invoice_id=i.id where f.scope='C';
select public.finish_invoice_issue(invoice_id,lease,external_id,'issued') from billing_fixture where scope='C';
update billing_fixture set lease=public.claim_invoice_cancellation(invoice_id) where scope='C';
select throws_ok($$select public.register_invoice_payment(invoice_id,gen_random_uuid(),1,'2033-01-04T12:00Z','cash','') from billing_fixture where scope='C'$$,'55P03',null,'payment cannot race a pending cancellation');
select public.mock_invoice_transition(external_id,'cancelled') from billing_fixture where scope='C';
select is((select public.finish_invoice_cancellation(invoice_id,lease) from billing_fixture where scope='C'),true,'unpaid invoice cancellation finalized');
select is((select status::text from public.invoices where id=(select invoice_id from billing_fixture where scope='C')),'cancelled','cancellation keeps immutable history');
select is((select public.claim_invoice_cancellation(invoice_id) from billing_fixture where scope='C'),null::uuid,'cancellation retry is idempotent');
select throws_ok($$select public.claim_invoice_cancellation(invoice_id) from billing_fixture where scope='A'$$,'23514',null,'paid invoice cannot be cancelled');
-- B starts at provider draft and is emitted by a verified callback with no human identity.
select public.mock_invoice_put(i.id,i.idempotency_key,repeat('f',64),'draft') from public.invoices i join billing_fixture f on f.invoice_id=i.id where f.scope='B';
select public.finish_invoice_issue(invoice_id,lease,external_id,'draft') from billing_fixture where scope='B';
select throws_ok($$select public.apply_invoice_webhook('mock','forged',external_id,'issued') from billing_fixture where scope='B'$$,'42501',null,'authenticated users cannot invoke callback service RPC');
reset role;set local role service_role;set local request.jwt.claim.role='service_role';set local request.jwt.claim.sub='';
select is((select public.apply_invoice_webhook('mock','billing-event-1',external_id,'issued') from billing_fixture where scope='B'),true,'verified callback issues invoice without impersonating a user');
select is((select status::text from public.orders where id=(select order_id from isolation_scopes where scope='B')),'invoiced','callback order transition is authorized narrowly');
select is((select public.apply_invoice_webhook('mock','billing-event-1',external_id,'issued') from billing_fixture where scope='B'),false,'callback replay is deduplicated');
select throws_ok($$select public.apply_invoice_webhook('mock','billing-event-1',external_id,'sent') from billing_fixture where scope='B'$$,'23505',null,'same callback ID with a different status conflicts');
select is((select public.apply_invoice_webhook('mock','billing-event-paid',external_id,'paid') from billing_fixture where scope='B'),true,'provider paid signal accepted');
select is((select status::text from public.invoices where id=(select invoice_id from billing_fixture where scope='B')),'issued','provider paid signal never fabricates a payment');
select is((select balance_cents from public.v_invoice_balances where id=(select invoice_id from billing_fixture where scope='B')),'1220','provider paid signal retains exact unsettled balance');
select public.apply_invoice_webhook('mock','billing-event-stale',external_id,'issued') from billing_fixture where scope='B';
select is((select external_status from public.invoices where id=(select invoice_id from billing_fixture where scope='B')),'paid','delayed callback cannot regress external terminal status');
reset role;
select is((select count(*) from public.invoice_webhook_events where invoice_id=(select invoice_id from billing_fixture where scope='B')),3::bigint,'distinct callbacks retain transactional history');
select ok(exists(select 1 from public.audit_log where table_name='payments' and record_id in(select id from public.payments where invoice_id=(select invoice_id from billing_fixture where scope='A'))),'payments have transactional audit');
select * from finish();rollback;
